begin;
create table public.staff_roles(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('admin','editor','writer','moderator')));
alter table public.staff_roles enable row level security;
create policy staff_self_read on public.staff_roles for select to authenticated using(user_id=auth.uid());
create function public.has_staff_role(roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.staff_roles where user_id=auth.uid() and role=any(roles)) $$;
revoke all on function public.has_staff_role(text[]) from public;
grant execute on function public.has_staff_role(text[]) to authenticated;
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(char_length(display_name) between 1 and 60), bio text not null default '' check(char_length(bio)<=500));
alter table public.profiles enable row level security;
create policy profiles_read on public.profiles for select using(true);
create policy profiles_insert on public.profiles for insert to authenticated with check(user_id=auth.uid());
create policy profiles_update on public.profiles for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.articles add column author_id uuid references auth.users(id) on delete set null, add column summary text not null default '', add column category text, add column tags text[] not null default '{}';
create policy editorial_manage on public.articles for all to authenticated using(public.has_staff_role(array['admin','editor'])) with check(public.has_staff_role(array['admin','editor']));
create policy games_manage on public.games for all to authenticated using(public.has_staff_role(array['admin','editor'])) with check(public.has_staff_role(array['admin','editor']));
create policy critics_manage on public.critic_reviews for all to authenticated using(public.has_staff_role(array['admin','editor'])) with check(public.has_staff_role(array['admin','editor']));
create table public.editorial_drafts(id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, title text not null, kind text not null check(kind in ('game','review','news')), content jsonb not null default '{}', status text not null default 'draft' check(status in ('draft','in_review','approved')), planned_at timestamptz, created_at timestamptz not null default now());
alter table public.editorial_drafts enable row level security;
create policy draft_read on public.editorial_drafts for select to authenticated using((owner_id=auth.uid() and public.has_staff_role(array['writer'])) or public.has_staff_role(array['admin','editor']));
create policy draft_insert on public.editorial_drafts for insert to authenticated with check(owner_id=auth.uid() and status='draft' and public.has_staff_role(array['writer','admin','editor']));
create policy draft_writer_update on public.editorial_drafts for update to authenticated using(owner_id=auth.uid() and status in ('draft','in_review') and public.has_staff_role(array['writer'])) with check(owner_id=auth.uid() and status in ('draft','in_review') and public.has_staff_role(array['writer']));
create policy draft_editor_manage on public.editorial_drafts for all to authenticated using(public.has_staff_role(array['admin','editor'])) with check(public.has_staff_role(array['admin','editor']));
create table public.publisher_submissions(id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, company text not null, contact_email text not null, kind text not null, details text not null, status text not null default 'submitted' check(status in ('submitted','reviewing','accepted','declined')), created_at timestamptz not null default now());
alter table public.publisher_submissions enable row level security;
create policy submission_insert on public.publisher_submissions for insert to authenticated with check(owner_id=auth.uid() and status='submitted');
create policy submission_read on public.publisher_submissions for select to authenticated using(owner_id=auth.uid() or public.has_staff_role(array['admin','editor']));
create policy submission_staff_update on public.publisher_submissions for update to authenticated using(public.has_staff_role(array['admin','editor'])) with check(public.has_staff_role(array['admin','editor']));
create table public.content_reports(id uuid primary key default gen_random_uuid(), reporter_id uuid default auth.uid() references auth.users(id) on delete set null, target_url text not null, reason text not null check(char_length(reason) between 1 and 2000), status text not null default 'open' check(status in ('open','resolved','dismissed')), created_at timestamptz not null default now());
alter table public.content_reports enable row level security;
create policy report_insert on public.content_reports for insert to authenticated with check(reporter_id=auth.uid() and status='open');
create policy report_staff_read on public.content_reports for select to authenticated using(public.has_staff_role(array['admin','moderator']));
create policy report_staff_update on public.content_reports for update to authenticated using(public.has_staff_role(array['admin','moderator'])) with check(public.has_staff_role(array['admin','moderator']));
create table public.audit_events(id bigint generated always as identity primary key, actor uuid, action text not null, entity text not null, entity_id uuid, created_at timestamptz not null default now());
alter table public.audit_events enable row level security;
create policy audit_read on public.audit_events for select to authenticated using(public.has_staff_role(array['admin']));
create function public.record_editorial_event() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.audit_events(actor,action,entity,entity_id) values(auth.uid(),TG_OP,TG_TABLE_NAME,case when TG_OP='DELETE' then old.id else new.id end); if TG_OP='DELETE' then return old; end if; return new; end $$;
revoke all on function public.record_editorial_event() from public;
create trigger articles_audit after insert or update or delete on public.articles for each row execute function public.record_editorial_event();
create trigger submissions_audit after insert or update or delete on public.publisher_submissions for each row execute function public.record_editorial_event();
create trigger reports_audit after insert or update or delete on public.content_reports for each row execute function public.record_editorial_event();
commit;